// Staff training ("ASTRA Academy").
//
// Traders: a real parameter search. Each trader backtests a grid of intraday strategies (momentum and
// mean reversion; look-back, entry threshold, stop) on practice sessions generated by the same market
// model as the live office, picks the best by risk-adjusted return, then checks it on held-out sessions it
// never saw. The strategy only goes live if it also holds up out of sample; otherwise the trader is told to
// keep turnover low (on a random-walk tape that is the honest lesson most of the time).
//
// Other roles: training sessions in the Training Room raise a skill score (with diminishing returns) that
// changes their simulated output (research speed, break resolution, café service, incident fixing).
// Everything here is paper / simulated: no real money, no real market.
import type { RoleType } from '../config/types';
import { hashRand } from '../util/rng';
import { INSTRUMENTS, INSTRUMENT_INDEX, Market } from './market';

export interface TraderStrategy {
  kind: 'momentum' | 'meanrev';
  lookback: number;
  threshold: number;
  stopPct: number;
}

export interface BacktestMetrics {
  /** Sum of daily returns on the traded overlay, as a fraction of overlay notional. */
  total: number;
  sharpe: number;
  maxDD: number;
  trades: number;
  hitRate: number;
  days: number;
}

export interface StrategyResult {
  strategy: TraderStrategy;
  /** Goes live only if the held-out sessions confirm the in-sample result. */
  active: boolean;
  train: BacktestMetrics;
  valid: BacktestMetrics;
  tested: number;
  symbols: string[];
  verdict: string;
  /** 'backtest': chosen on practice sessions; 'forward': chosen from live regime data and proven on live paper trades. */
  mode?: 'backtest' | 'forward';
  /** Live paper results since the strategy went live. */
  forward?: { trades: number; wins: number; pnl: number };
}

export interface ModuleResult { id: string; title: string; score: number; passed: boolean; day: number; minute: number }

export interface TrainingRecord {
  empId: string;
  role: RoleType;
  /** 0-100. Starts from prior experience; each passed module adds part of the remaining gap. */
  skill: number;
  modules: ModuleResult[];
  strategy?: StrategyResult;
  /** Personal coaching after mistakes: one-to-one sessions with their manager. */
  coaching?: { kind: string; text: string; day: number; status: 'due' | 'booked' | 'done' }[];
  mistakes?: number;
}

