export const PASS_MARK = 70;

/** Prior experience before any training (deterministic per person). */
export function baseSkill(seed: number, empId: string): number {
  return Math.round(35 + hashRand(seed, 'skill0', empId) * 30);
}

export function newRecord(seed: number, empId: string, role: RoleType): TrainingRecord {
  return { empId, role, skill: baseSkill(seed, empId), modules: [] };
}

/** Next module in the person's curriculum (the first not yet passed), or null when certified. */
export function nextModule(rec: TrainingRecord): { id: string; title: string } | null {
  return CURRICULA[rec.role].find((m) => !rec.modules.some((r) => r.id === m.id && r.passed)) ?? null;
}

export function certified(rec: TrainingRecord): boolean {
  return nextModule(rec) === null;
}

/** Sit a module: assessment score depends on current skill and effort on the day; passing raises skill. */
export function completeModule(seed: number, rec: TrainingRecord, mod: { id: string; title: string }, day: number, minute: number, bonus = 0): ModuleResult {
  const attempt = rec.modules.filter((m) => m.id === mod.id).length;
  const score = Math.max(0, Math.min(100, Math.round(rec.skill * 0.55 + 30 + hashRand(seed, 'exam', rec.empId, mod.id, attempt) * 25 + bonus + attempt * 6)));
  const passed = score >= PASS_MARK;
  rec.skill = Math.min(100, Math.round(rec.skill + (100 - rec.skill) * (passed ? 0.3 : 0.1)));
  const r: ModuleResult = { id: mod.id, title: mod.title, score, passed, day, minute };
  rec.modules.push(r);
  return r;
}

/** Output multiplier from skill: 0.7 at 0, 1.0 at 50, 1.3 at 100. */
export function skillFactor(skill: number): number {
  return 0.7 + (skill / 100) * 0.6;
}

// ------------------------------------------------------------------ backtesting
const SESSION_START = 8 * 60 + 30;
const SESSION_END = 17 * 60;
export const TRAIN_DAYS = 28;
export const VALID_DAYS = 8;
/** Cost per side (half-spread + fees) as a fraction of notional, for institutional size. */
const COST = 0.00005;

/**
 * Practice sessions from the office market model with an independent seed: [instrument][day][minute].
 * The first TRAIN_DAYS are in-sample; the last VALID_DAYS are held out. Built a session at a time so the
 * browser stays responsive while the desk "replays" the practice tape.
 */
export class PracticeTape {
  readonly sessions: Float64Array[][] = INSTRUMENTS.map(() => []);
  private day = 0;
  private m: Market;

  constructor(seed: number) {
    this.m = new Market(Math.floor(hashRand(seed, 'practice-tape') * 1e9), SESSION_START);
  }

  get ready(): boolean {
    return this.day >= TRAIN_DAYS + VALID_DAYS;
  }

  get progress(): number {
    return this.day / (TRAIN_DAYS + VALID_DAYS);
  }

  /** Generate up to n more sessions. Returns true when the tape is complete. */
  step(n = 1): boolean {
    for (let i = 0; i < n && !this.ready; i++) {
      this.m.newDay(this.day, SESSION_START);
      this.m.advanceTo(SESSION_END);
      INSTRUMENTS.forEach((_, k) => this.sessions[k].push(Float64Array.from(this.m.history[k])));
      this.day++;
    }
    return this.ready;
  }
}

const tapes = new Map<number, PracticeTape>();

export function practiceTape(seed: number): PracticeTape {
  let t = tapes.get(seed);
  if (!t) { t = new PracticeTape(seed); tapes.set(seed, t); }
  return t;
}

export function practiceSessions(seed: number): Float64Array[][] {
  const t = practiceTape(seed);
  t.step(Infinity);
  return t.sessions;
}

/** Signal for the latest point of a price series: -1, 0 or +1 (null when there is not enough data). */
export function signalAt(s: TraderStrategy, prices: ArrayLike<number>, i: number): { z: number; sig: number } | null {
  if (i < s.lookback) return null;
  let sum = 0;
  let sq = 0;
  for (let j = i - s.lookback; j < i; j++) { sum += prices[j]; sq += prices[j] * prices[j]; }
  const mean = sum / s.lookback;
  const sd = Math.sqrt(Math.max(0, sq / s.lookback - mean * mean));
  if (sd <= mean * 1e-6) return { z: 0, sig: 0 };
  const z = (prices[i] - mean) / sd;
  let sig = z > s.threshold ? 1 : z < -s.threshold ? -1 : 0;
  if (s.kind === 'meanrev') sig = -sig;
  return { z, sig };
}

/** Exit rule shared by the backtest and live trading. */
export function shouldExit(s: TraderStrategy, pos: number, z: number, px: number, entry: number): boolean {
  if (pos === 0) return false;
  if ((px / entry - 1) * pos < -s.stopPct) return true; // stop loss
  return s.kind === 'momentum' ? z * pos <= 0 : z * pos >= 0;
}

/** One session for one symbol: returns the day's return on the overlay and trade stats (rolling sums, O(n)). */
function runDay(s: TraderStrategy, p: Float64Array): { ret: number; trades: number; wins: number } {
  let pos = 0;
  let entry = 0;
  let ret = 0;
  let trades = 0;
  let wins = 0;
  const L = s.lookback;
  let sum = 0;
  let sq = 0;
  for (let j = 0; j < L; j++) { sum += p[j]; sq += p[j] * p[j]; }
  for (let i = L; i < p.length; i++) {
    if (pos !== 0) ret += pos * (p[i] / p[i - 1] - 1);
    const mean = sum / L;
    const sd = Math.sqrt(Math.max(0, sq / L - mean * mean));
    const z = sd > mean * 1e-6 ? (p[i] - mean) / sd : 0;
    let sig = z > s.threshold ? 1 : z < -s.threshold ? -1 : 0;
    if (s.kind === 'meanrev') sig = -sig;
    if (pos !== 0 && shouldExit(s, pos, z, p[i], entry)) {
      if ((p[i] / entry - 1) * pos > 0) wins++;
      ret -= COST;
      pos = 0;
    }
    if (pos === 0 && sig !== 0 && i < p.length - 10) {
      pos = sig;
      entry = p[i];
      ret -= COST;
      trades++;
    }
    sum += p[i] - p[i - L];
    sq += p[i] * p[i] - p[i - L] * p[i - L];
  }
  if (pos !== 0) {
    if ((p[p.length - 1] / entry - 1) * pos > 0) wins++;
    ret -= COST;
  }
  return { ret, trades, wins };
}

function metrics(daily: number[], trades: number, wins: number): BacktestMetrics {
  const n = daily.length || 1;
  const mean = daily.reduce((a, b) => a + b, 0) / n;
  const sd = Math.sqrt(daily.reduce((a, b) => a + (b - mean) ** 2, 0) / n) || 1e-9;
  let eq = 0;
  let peak = 0;
  let dd = 0;
  for (const r of daily) { eq += r; peak = Math.max(peak, eq); dd = Math.max(dd, peak - eq); }
  return { total: mean * n, sharpe: (mean / sd) * Math.sqrt(252), maxDD: dd, trades, hitRate: trades ? wins / trades : 0, days: daily.length };
}

export function backtest(s: TraderStrategy, symbols: string[], sessions: Float64Array[][], from: number, to: number): BacktestMetrics {
  const daily: number[] = [];
  let trades = 0;
  let wins = 0;
  for (let d = from; d < to; d++) {
    let r = 0;
    for (const sym of symbols) {
      const res = runDay(s, sessions[INSTRUMENT_INDEX.get(sym)!][d]);
      r += res.ret / symbols.length;
      trades += res.trades;
      wins += res.wins;
    }
    daily.push(r);
  }
  return metrics(daily, trades, wins);
}

export const STRATEGY_GRID: TraderStrategy[] = (['momentum', 'meanrev'] as const).flatMap((kind) =>
  [10, 20, 40].flatMap((lookback) => [1.0, 1.5, 2.0, 2.5].flatMap((threshold) => [0.003, 0.006].map((stopPct) => ({ kind, lookback, threshold, stopPct })))));

export function describeStrategy(s: TraderStrategy): string {
  return `${s.kind === 'momentum' ? 'Momentum' : 'Mean reversion'} (look-back ${s.lookback} min, entry ±${s.threshold.toFixed(1)}σ, stop ${(s.stopPct * 100).toFixed(1)}%)`;
}

/** Grid search on the in-sample sessions, then a check on held-out sessions. */
export function trainStrategy(seed: number, symbols: string[]): StrategyResult {
  const sessions = practiceSessions(seed);
  let best: { s: TraderStrategy; m: BacktestMetrics } | null = null;
  for (const s of STRATEGY_GRID) {
    const m = backtest(s, symbols, sessions, 0, TRAIN_DAYS);
    if (m.trades < TRAIN_DAYS) continue; // needs at least ~1 trade a day to say anything
    if (!best || m.sharpe > best.m.sharpe) best = { s, m };
  }
  if (!best) best = { s: STRATEGY_GRID[0], m: backtest(STRATEGY_GRID[0], symbols, sessions, 0, TRAIN_DAYS) };
  const valid = backtest(best.s, symbols, sessions, TRAIN_DAYS, TRAIN_DAYS + VALID_DAYS);
  const active = best.m.sharpe > 0.5 && valid.sharpe > 0.5 && valid.total > 0;
  const pct = (x: number) => `${(x * 100).toFixed(2)}%`;
  const verdict = active
    ? `Live: ${describeStrategy(best.s)} held up on unseen sessions (Sharpe ${valid.sharpe.toFixed(2)}, return ${pct(valid.total)}).`
    : `Not used: best in-sample ${describeStrategy(best.s)} (Sharpe ${best.m.sharpe.toFixed(2)}) did not hold up on unseen sessions (Sharpe ${valid.sharpe.toFixed(2)}, return ${pct(valid.total)}). Keep turnover low and hold core positions.`;
  return { strategy: best.s, active, train: best.m, valid, tested: STRATEGY_GRID.length, symbols, verdict };
}

// ------------------------------------------------------------------ live mode
export interface Indicators { price: number; rsi?: number; sma20?: number; sma50?: number; sma200?: number }

/**
 * Live markets have no practice tape here, so the lab reads the current regime from real indicators
 * (price vs 50/200-hour averages, RSI) and starts a forward test: small size, real prices, paper money.
 * The strategy is promoted after 8 profitable round trips and suspended if it loses money.
 */
export function liveLabStrategy(symbols: string[], ind: Map<string, Indicators>): StrategyResult {
  let trend = 0;
  let read = 0;
  const notes: string[] = [];
  for (const sym of symbols) {
    const i = ind.get(sym);
    if (!i || i.sma50 === undefined || i.sma200 === undefined) continue;
    read++;
    const up = i.price > i.sma50 && i.sma50 > i.sma200;
    const down = i.price < i.sma50 && i.sma50 < i.sma200;
    trend += up ? 1 : down ? -1 : 0;
    notes.push(`${sym} ${up ? 'up-trend' : down ? 'down-trend' : 'range'}${i.rsi !== undefined ? `, RSI ${i.rsi.toFixed(0)}` : ''}`);
  }
  const trending = read > 0 && Math.abs(trend) === read;
  const strategy: TraderStrategy = trending
    ? { kind: 'momentum', lookback: 20, threshold: 1.5, stopPct: 0.006 }
    : { kind: 'meanrev', lookback: 20, threshold: 2.0, stopPct: 0.006 };
  const none: BacktestMetrics = { total: 0, sharpe: 0, maxDD: 0, trades: 0, hitRate: 0, days: 0 };
  const regime = read ? notes.join('; ') : 'no indicator data (connector unavailable)';
  return {
    strategy, active: read > 0, train: none, valid: none, tested: 2, symbols, mode: 'forward', forward: { trades: 0, wins: 0, pnl: 0 },
    verdict: read
      ? `Forward test: ${describeStrategy(strategy)} chosen from live regime (${regime}). Trades small on live prices (paper); promoted after 8 profitable round trips, suspended if it loses money.`
      : 'Not used: no live indicator data, so no regime read. Hold core positions.',
  };
}
